'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId, useState } from 'react';

import { SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';
import { Kbd, KbdGroup } from '@/registry/ndeko/ui/kbd';

import {
  AsideCloseButton,
  AsideDescription,
  AsidePreview,
  AsideTitle,
} from './_parts/aside-frame';
import { rowVariantsOf } from './_parts/motion';

/** Each stroke is a set of keys pressed together; several strokes are pressed one after the other. */
type Shortcut = { id: string; label: string; strokes: string[][] };

type ShortcutGroup = { id: string; title: string; shortcuts: Shortcut[] };

const GROUPS: ShortcutGroup[] = [
  {
    id: 'general',
    title: 'General',
    shortcuts: [
      { id: 'command', label: 'Open the command menu', strokes: [['⌘', 'K']] },
      { id: 'search', label: 'Search tasks', strokes: [['/']] },
      { id: 'shortcuts', label: 'Show keyboard shortcuts', strokes: [['?']] },
    ],
  },
  {
    id: 'navigation',
    title: 'Navigation',
    shortcuts: [
      { id: 'go-inbox', label: 'Go to the inbox', strokes: [['G'], ['I']] },
      { id: 'go-tasks', label: 'Go to my tasks', strokes: [['G'], ['T']] },
      {
        id: 'go-timesheets',
        label: 'Go to timesheets',
        strokes: [['G'], ['S']],
      },
      { id: 'next', label: 'Next task', strokes: [['J']] },
      { id: 'previous', label: 'Previous task', strokes: [['K']] },
    ],
  },
  {
    id: 'tasks',
    title: 'Tasks',
    shortcuts: [
      { id: 'create', label: 'Create a task', strokes: [['C']] },
      { id: 'assign', label: 'Assign to me', strokes: [['I']] },
      { id: 'status', label: 'Change the status', strokes: [['S']] },
      { id: 'priority', label: 'Set the priority', strokes: [['P']] },
      { id: 'timer', label: 'Start or stop the timer', strokes: [['T']] },
      { id: 'copy', label: 'Copy the task link', strokes: [['⌘', '⇧', 'C']] },
    ],
  },
];

function normalized(text: string) {
  const trimmed = text.trim();
  return trimmed.toLowerCase();
}

function matchesQuery(shortcut: Shortcut, query: string) {
  if (query.length === 0) {
    return true;
  }
  const label = shortcut.label.toLowerCase();
  return label.includes(query);
}

function matchCountLabel(count: number) {
  if (count === 1) {
    return '1 shortcut';
  }
  return `${count} shortcuts`;
}

function HighlightedLabel({ label, query }: { label: string; query: string }) {
  const lowerLabel = label.toLowerCase();
  const start = lowerLabel.indexOf(query);
  const hasMatch = query.length > 0 && start >= 0;
  if (!hasMatch) {
    return <span>{label}</span>;
  }
  const end = start + query.length;
  const before = label.slice(0, start);
  const match = label.slice(start, end);
  const after = label.slice(end);

  return (
    <span>
      {before}
      <mark className='bg-primary/15 text-foreground rounded-[3px]'>
        {match}
      </mark>
      {after}
    </span>
  );
}

function Strokes({ strokes }: { strokes: string[][] }) {
  return (
    <span className='flex shrink-0 items-center gap-1.5'>
      {strokes.map((keys, index) => {
        const isFollowUp = index > 0;

        return (
          <span key={keys.join('+')} className='flex items-center gap-1.5'>
            {isFollowUp && (
              <span className='text-muted-foreground text-[11px]'>then</span>
            )}
            <KbdGroup>
              {keys.map((key) => (
                <Kbd key={key}>{key}</Kbd>
              ))}
            </KbdGroup>
          </span>
        );
      })}
    </span>
  );
}

function KeyboardShortcuts() {
  const [query, setQuery] = useState('');
  const searchId = useId();
  const shouldReduceMotion = useReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const normalizedQuery = normalized(query);
  const visibleGroups = GROUPS.map((group) => ({
    ...group,
    shortcuts: group.shortcuts.filter((shortcut) =>
      matchesQuery(shortcut, normalizedQuery)
    ),
  }));
  let matchCount = 0;
  for (const group of visibleGroups) {
    matchCount += group.shortcuts.length;
  }
  const hasMatches = matchCount > 0;

  function changeQuery(event: React.ChangeEvent<HTMLInputElement>) {
    setQuery(event.target.value);
  }

  function clearQuery() {
    setQuery('');
  }

  return (
    <div className='flex flex-col gap-5 p-5'>
      <div className='flex items-start gap-3'>
        <div className='flex min-w-0 flex-1 flex-col gap-1'>
          <AsideTitle>Keyboard shortcuts</AsideTitle>
          <AsideDescription>{matchCountLabel(matchCount)}</AsideDescription>
        </div>
        <AsideCloseButton label='Close shortcuts' className='-mt-1 -mr-2' />
      </div>
      <div className='relative'>
        <label htmlFor={searchId} className='sr-only'>
          Filter shortcuts
        </label>
        <SearchIcon className='text-muted-foreground pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2' />
        <Input
          id={searchId}
          type='search'
          value={query}
          placeholder='Filter by action'
          onChange={changeQuery}
          className='pl-8'
        />
      </div>
      <div className='-mt-3 flex flex-col'>
        <AnimatePresence initial={false}>
          {!hasMatches && (
            <motion.div
              key='empty'
              variants={rowVariants}
              initial='hidden'
              animate='shown'
              exit='hidden'
            >
              <div className='flex flex-col items-start gap-2 pt-3'>
                <p className='text-[13px]'>
                  {`No shortcut matches “${query.trim()}”`}
                </p>
                <Button variant='outline' size='sm' onClick={clearQuery}>
                  <XIcon />
                  Clear filter
                </Button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
        <AnimatePresence initial={false}>
          {visibleGroups.map((group) => {
            const hasShortcuts = group.shortcuts.length > 0;
            if (!hasShortcuts) {
              return null;
            }

            return (
              <motion.section
                key={group.id}
                aria-label={group.title}
                variants={rowVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <h3 className='text-muted-foreground pt-3 pb-1 text-xs font-medium'>
                  {group.title}
                </h3>
                <ul className='flex flex-col'>
                  <AnimatePresence initial={false}>
                    {group.shortcuts.map((shortcut) => (
                      <motion.li
                        key={shortcut.id}
                        variants={rowVariants}
                        initial='hidden'
                        animate='shown'
                        exit='hidden'
                      >
                        <div className='flex min-h-9 items-center gap-3 text-[13px]'>
                          <span className='min-w-0 flex-1'>
                            <HighlightedLabel
                              label={shortcut.label}
                              query={normalizedQuery}
                            />
                          </span>
                          <Strokes strokes={shortcut.strokes} />
                        </div>
                      </motion.li>
                    ))}
                  </AnimatePresence>
                </ul>
              </motion.section>
            );
          })}
        </AnimatePresence>
      </div>
    </div>
  );
}

export default function Aside07() {
  return (
    <AsidePreview triggerLabel='Open keyboard shortcuts'>
      <KeyboardShortcuts />
    </AsidePreview>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { PanelsTopLeftIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

/** Where an aside's content is drawn: open in the page as a preview, or inside the real sheet. */
export type AsideHost = 'preview' | 'sheet';

const AsideHostContext = createContext<AsideHost>('preview');

export function useAsideHost() {
  return useContext(AsideHostContext);
}

export type AsideSide = 'left' | 'right';

const TITLE = 'text-lg leading-tight font-semibold';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

/** The background of the surface the aside sits on, for parts that must cover what scrolls under them. */
export const ASIDE_SURFACE = 'bg-[var(--aside-surface)]';

type AsideTextProps = { className?: string; children: React.ReactNode };

export function AsideTitle({ className, children }: AsideTextProps) {
  const host = useAsideHost();
  if (host === 'sheet') {
    return <SheetTitle className={className}>{children}</SheetTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function AsideDescription({ className, children }: AsideTextProps) {
  const host = useAsideHost();
  if (host === 'sheet') {
    return (
      <SheetDescription className={className}>{children}</SheetDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** The close button of the sheet's header. The preview has nothing to close, so it draws nothing. */
export function AsideCloseButton({
  label = 'Close panel',
  className,
}: {
  label?: string;
  className?: string;
}) {
  const host = useAsideHost();
  if (host === 'preview') {
    return null;
  }
  return (
    <SheetClose
      render={
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label={label}
          className={cn('text-muted-foreground', className)}
        />
      }
    >
      <XIcon />
    </SheetClose>
  );
}

type AsidePreviewProps = {
  /** The content, drawn twice: open in the page, and inside the sheet the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  side?: AsideSide;
  className?: string;
};

/** Shows an aside open and whole on the page, with a small trigger that slides the same content in as a real sheet. */
export function AsidePreview({
  children,
  triggerLabel,
  side = 'right',
  className,
}: AsidePreviewProps) {
  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <AsideHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised flex w-full max-w-sm flex-col overflow-hidden rounded-2xl text-left [--aside-surface:var(--popover)]',
            className
          )}
        >
          {children}
        </div>
      </AsideHostContext.Provider>
      <Sheet>
        <SheetTrigger render={<Button variant='outline' size='sm' />}>
          <PanelsTopLeftIcon />
          {triggerLabel}
        </SheetTrigger>
        <SheetContent
          side={side}
          showCloseButton={false}
          className={cn('gap-0 p-0 [--aside-surface:var(--card)]', className)}
        >
          <AsideHostContext.Provider value='sheet'>
            {children}
          </AsideHostContext.Provider>
        </SheetContent>
      </Sheet>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const TRAVEL_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const ENTER: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const LEAVE: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const HEIGHT_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, overflow: 'hidden', transition: LEAVE },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ENTER,
    transitionEnd: { overflow: 'visible' },
  },
};

const FADE_PRESENCE: Variants = {
  hidden: { opacity: 0, transition: LEAVE },
  shown: { opacity: 1, transition: ENTER },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: LEAVE },
  shown: { opacity: 1, scale: 1, transition: ENTER },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row that joins or leaves a list: its height opens or collapses, so what follows slides instead of jumping. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return CHIP_PRESENCE;
}

export function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL_SPRING;
}
